package hosting

// Framework presets: front controller rules generated for Nginx or Apache,
// adapted to the webdevops images (PHP-FPM upstream "php", site mounted in
// /app). Bump SpecVersion when changing their output: generated files of the
// current version are compared with it to detect manual edits.

import (
	"fmt"
	"path"
	"strings"
)

// SymfonyRules generates the front controller rules recommended by the
// Symfony documentation for the web server of a template, adapted to the
// webdevops images (PHP-FPM upstream "php", site mounted in /app).
func SymfonyRules(t Template, documentRoot string, assetDirs []string, timeoutSeconds int) string {
	var b strings.Builder
	if t.UsesNginx() {
		b.WriteString("# Symfony front controller (generated by Loch.sh Panel)\n")
		b.WriteString("# https://symfony.com/doc/current/setup/web_server_configuration.html\n\n")
		b.WriteString("location / {\n    # try to serve file directly, fallback to index.php\n    try_files $uri /index.php$is_args$args;\n}\n")
		for _, d := range assetDirs {
			fmt.Fprintf(&b, "\n# serve assets without falling back to Symfony\nlocation /%s {\n    try_files $uri =404;\n}\n", d)
		}
		fmt.Fprintf(&b, `
location ~ ^/index\.php(/|$) {
    fastcgi_split_path_info ^(.+\.php)(/.*)$;
    fastcgi_pass php;
    include fastcgi_params;
    fastcgi_param SCRIPT_FILENAME $realpath_root$fastcgi_script_name;
    fastcgi_param DOCUMENT_ROOT $realpath_root;
    fastcgi_read_timeout %ds;
    # prevents URIs that include the front controller (/index.php/some-path)
    internal;
}

# return 404 for all other php files not matching the front controller
location ~ \.php$ {
    return 404;
}
`, timeoutSeconds)
		return b.String()
	}

	root := path.Join(appMountPoint, documentRoot)
	b.WriteString("# Symfony front controller (generated by Loch.sh Panel)\n")
	b.WriteString("# https://symfony.com/doc/current/setup/web_server_configuration.html\n\n")
	b.WriteString(apacheFrontController(root, "None"))
	for _, d := range assetDirs {
		fmt.Fprintf(&b, "\n# serve assets without falling back to Symfony\n<Directory \"%s\">\n    DirectoryIndex disabled\n    FallbackResource disabled\n</Directory>\n", path.Join(root, d))
	}
	return b.String()
}

// LaravelRules generates the front controller rules recommended by the
// Laravel documentation for the web server of a template.
func LaravelRules(t Template, documentRoot string, timeoutSeconds int) string {
	var b strings.Builder
	b.WriteString("# Laravel front controller (generated by Loch.sh Panel)\n")
	b.WriteString("# https://laravel.com/docs/deployment#server-configuration\n\n")
	if t.UsesNginx() {
		fmt.Fprintf(&b, `location / {
    try_files $uri $uri/ /index.php?$query_string;
}

location = /favicon.ico { access_log off; log_not_found off; }
location = /robots.txt  { access_log off; log_not_found off; }

error_page 404 /index.php;

location ~ ^/index\.php(/|$) {
    fastcgi_pass php;
    include fastcgi_params;
    fastcgi_param SCRIPT_FILENAME $realpath_root$fastcgi_script_name;
    fastcgi_param DOCUMENT_ROOT $realpath_root;
    fastcgi_read_timeout %ds;
    fastcgi_hide_header X-Powered-By;
}

# deny dotfiles (.env, .git...), except .well-known
location ~ /\.(?!well-known(/|$)) {
    deny all;
}

# return 404 for all other php files not matching the front controller
location ~ \.php$ {
    return 404;
}
`, timeoutSeconds)
		return b.String()
	}

	root := path.Join(appMountPoint, documentRoot)
	// AllowOverride All: Laravel ships its own public/.htaccess (the image
	// already allows it globally, this keeps it explicit).
	b.WriteString(apacheFrontController(root, "All"))
	b.WriteString(`
# deny dotfiles (.env, .git...), except .well-known
<LocationMatch "/\.(?!well-known(/|$))">
    Require all denied
</LocationMatch>
`)
	return b.String()
}

// apacheFrontController is the Apache part shared by the framework presets:
// every request falls back to index.php, which is the only PHP file allowed
// to run (the image sends any *.php to PHP-FPM otherwise, so a script under
// vendor/ or an uploaded file would execute), and the Authorization header is
// passed to PHP (API tokens, HTTP basic auth).
func apacheFrontController(root, allowOverride string) string {
	return fmt.Sprintf(`<Directory "%s">
    Options -Indexes +FollowSymLinks
    AllowOverride %s
    Require all granted
    CGIPassAuth On
    FallbackResource /index.php
</Directory>

# only the front controller runs: other PHP files are denied
<FilesMatch "^(?!index\.php$).*\.php$">
    Require all denied
</FilesMatch>
`, root, allowOverride)
}
